def answer(query: str) -> Response:
    if cache.hit(query, threshold=0.90):
        return cache.get(query)

    # Hybrid retrieval: MiniLM dense + BM42 sparse
    dense, sparse = embed(query)
    hits = qdrant.hybrid_search(dense, sparse)

    # RAG-Fusion multi-query expansion
    hits += fusion.multi_query(query, hits)
    ranked = reranker.cross_encode(query, hits)

    # Chain-of-Thought synthesis
    return llm.reason(query, ranked, steps=4)
